# mapping_status 신뢰도 순위 (낮을수록 신뢰도 높음). 같은 (hs_code, sector_key) 또는
# (hs_code, stock_code) 조합에 나중 실행된 행이 등급이 더 낮은 상태(예: exact→provisional)로
# 덮어쓰는 회귀 버그가 실제로 있었음(2026-08-23, 9001100000/energy_materials·9027909099/biotech
# 두 건이 alias 표기용으로 나중에 추가된 provisional 행에 의해 exact/composite 검증이 유실됨).
# 재발 방지를 위해 기존 행의 상태가 더 좋으면 상태/표시명은 유지하고, 새 note는 참고용으로 덧붙인다.
_STATUS_RANK = {"exact": 1, "composite": 2, "provisional": 3}


def _resolve_no_downgrade(existing: tuple[str, str, str] | None, incoming_display: str, incoming_status: str, incoming_note: str) -> tuple[str, str, str]:
    """(display_name, mapping_status, note)를 반환. 기존 상태가 더 좋으면 낮추지 않는다."""
    if not existing:
        return incoming_display, incoming_status, incoming_note
    existing_display, existing_status, existing_note = existing
    if _STATUS_RANK.get(incoming_status, 3) >= _STATUS_RANK.get(existing_status, 3):
        merged_note = existing_note or ""
        if incoming_note and incoming_note not in merged_note:
            merged_note = f"{merged_note} | (별칭 참고) {incoming_note}" if merged_note else incoming_note
        return existing_display, existing_status, merged_note
    return incoming_display, incoming_status, incoming_note


def main() -> None:
    conn = sqlite3.connect(DB_PATH)
    for row in SECTOR_MAPS:
        if len(row) == 5:
            hs_code, hs_name, sector_key, display_name, note = row
            mapping_status = "provisional"
        else:
            hs_code, hs_name, sector_key, display_name, note, mapping_status = row

        existing = conn.execute(
            "SELECT display_name, mapping_status, note FROM hs_sector_map WHERE hs_code=? AND sector_key=?",
            (hs_code, sector_key),
        ).fetchone()
        display_name, mapping_status, note = _resolve_no_downgrade(existing, display_name, mapping_status, note)

        conn.execute(
            """
            INSERT INTO hs_sector_map (hs_code, hs_name, sector_key, display_name, mapping_status, note)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(hs_code, sector_key) DO UPDATE SET
                hs_name=excluded.hs_name,
                display_name=excluded.display_name,
                mapping_status=excluded.mapping_status,
                note=excluded.note,
                updated_at=CURRENT_TIMESTAMP
            """,
            (hs_code, hs_name, sector_key, display_name, mapping_status, note),
        )

    for row in COMPANY_MAPS:
        if len(row) == 6:
            hs_code, hs_name, stock_code, stock_name, sector_name, note = row
            confidence = 0.85
            mapping_status = "provisional"
        else:
            hs_code, hs_name, stock_code, stock_name, sector_name, note, confidence, mapping_status = row

        existing = conn.execute(
            "SELECT sector_name, mapping_status, note FROM hs_code_company_map WHERE hs_code=? AND stock_code=?",
            (hs_code, stock_code),
        ).fetchone()
        sector_name, mapping_status, note = _resolve_no_downgrade(existing, sector_name, mapping_status, note)

        conn.execute(
            """
            INSERT INTO hs_code_company_map
            (hs_code, hs_name, stock_code, stock_name, sector_name, match_type, mapping_status, confidence, note)
            VALUES (?, ?, ?, ?, ?, 'company', ?, ?, ?)
            ON CONFLICT(hs_code, stock_code) DO UPDATE SET
                hs_name=excluded.hs_name,
                stock_name=excluded.stock_name,
                sector_name=excluded.sector_name,
                mapping_status=excluded.mapping_status,
                confidence=excluded.confidence,
                note=excluded.note,
                updated_at=CURRENT_TIMESTAMP
            """,
            (hs_code, hs_name, stock_code, stock_name, sector_name, mapping_status, confidence, note),
        )
    conn.commit()
    conn.close()

    subprocess.run(
        [str(ROOT_DIR.parent / "venv" / "bin" / "python"), str(ROOT_DIR / "scripts" / "sync_master_data.py")],
        cwd=ROOT_DIR,
        check=True,
    )
    print({"sector_maps": len(SECTOR_MAPS), "company_maps": len(COMPANY_MAPS)})


if __name__ == "__main__":
    main()
